   483|  console.log('Blob URL:', url);
   484|}, 'image/png');
   485|
   486|// Canvas to Data URL (for inline embedding)
   487|let dataUrl = document.querySelector('canvas').toDataURL('image/png');
   488|// Use in <img src="..."> or send as base64
   489|```
